<?php
declare(strict_types=1);

require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/shop_attribute_admin.php';
if(!isset($_SESSION['trener_id'])||!roleAtLeast('admin')){header('Location: login.php');exit;}
function attributeAdminH(mixed$value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}

$errors=[];$actorId=(int)$_SESSION['trener_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel. Obnovte stránku.';
    else try{$result=shopAttributeAdminSave($pdo,$actorId,$_POST,(string)($_POST['reason']??''),($_POST['confirm_action']??'')==='1');$_SESSION['attribute_admin_flash']='Definice parametru byla auditovaně uložena.';header('Location: eshop_attributes_admin.php?id='.(int)$result['id'],true,303);exit;}catch(Throwable$exception){$errors[]=$exception->getMessage();}
}
$success=(string)($_SESSION['attribute_admin_flash']??'');unset($_SESSION['attribute_admin_flash']);
$definitions=shopAttributeDefinitions($pdo,true);$selectedId=max(0,(int)($_GET['id']??0));$selected=$selectedId>0?shopAttributeAdminDefinition($pdo,$selectedId):null;
if($selectedId>0&&$selected===null)$errors[]='Definice parametru nebyla nalezena.';
$discovered=shopAttributeDiscoveredKeys($pdo);$undefined=array_values(array_filter($discovered,static fn(string$key):bool=>!isset($definitions[$key])));$newKey=trim((string)($_GET['klic']??''));
$choiceText=$selected!==null?implode("\n",array_map(static fn(array$row):string=>(int)$row['active']===1?(string)$row['value']:'', $selected['choice_rows'])):'';
$events=$pdo->query("SELECT e.*,t.jmeno actor_name FROM shop_attribute_definition_events e LEFT JOIN treneri t ON e.actor_type='trainer' AND t.id=e.actor_id ORDER BY e.id DESC LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Parametry e-shopu</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH" crossorigin="anonymous"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" integrity="sha384-XGjxtQfXaH2tnPFa9x+ruJTuLE3Aa6LhHSWRr1XeTyhezb4abCG4ccI5AkVDxqC+" crossorigin="anonymous"></head><body class="bg-light"><?php include __DIR__.'/hlavicka.php';?>
<main class="container-fluid py-4" style="max-width:1500px"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><div><h1 class="h4 mb-0"><i class="bi bi-sliders me-2 text-primary"></i>Parametry produktů</h1><div class="small text-muted">Číselník názvů, jednotek a povolených hodnot používaných ve formulářích i u importovaných produktů.</div></div><div class="d-flex gap-2"><a class="btn btn-outline-primary btn-sm" href="eshop_produkt_admin.php">Produkty</a><a class="btn btn-outline-secondary btn-sm" href="eshop_admin.php">Zpět</a></div></div>
<?php foreach($errors as$error):?><div class="alert alert-danger"><?=attributeAdminH($error)?></div><?php endforeach;?><?php if($success!==''):?><div class="alert alert-success"><?=attributeAdminH($success)?></div><?php endif;?>
<div class="alert alert-info py-2">Neznámý klíč z importu se dál bezpečně zobrazí pod definovanými parametry. Deaktivace pouze skryje zobrazení; hodnoty ve variantách ani historii nemaže.</div>
<div class="row g-3"><section class="col-xl-7"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Definice (<?=count($definitions)?>)</div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Klíč</th><th>Název</th><th>Typ</th><th>Výpis</th><th>Detail</th><th>Stav</th><th></th></tr></thead><tbody><?php foreach($definitions as$definition):?><tr><td><code><?=attributeAdminH($definition['attribute_key'])?></code></td><td><?=attributeAdminH($definition['display_name'])?><?php if((string)($definition['unit']??'')!==''):?><span class="text-muted"> · <?=attributeAdminH($definition['unit'])?></span><?php endif;?></td><td><?=attributeAdminH($definition['value_type'])?></td><td><?=(int)$definition['show_in_listing']===1?'ano':'ne'?></td><td><?=(int)$definition['show_in_detail']===1?'ano':'ne'?></td><td><?=(int)$definition['active']===1?'<span class="badge text-bg-success">aktivní</span>':'<span class="badge text-bg-secondary">skrytý</span>'?></td><td><a class="btn btn-sm btn-outline-primary" href="eshop_attributes_admin.php?id=<?=(int)$definition['id']?>">Upravit</a></td></tr><?php endforeach;?><?php if($definitions===[]):?><tr><td colspan="7" class="text-center text-muted py-4">Zatím bez definic. Importované parametry přesto zůstávají funkční.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card border-0 shadow-sm mt-3"><div class="card-header bg-white fw-semibold">Objevené klíče bez definice (<?=count($undefined)?>)</div><div class="card-body d-flex flex-wrap gap-2"><?php foreach($undefined as$key):?><a class="btn btn-sm btn-outline-secondary" href="eshop_attributes_admin.php?klic=<?=rawurlencode($key)?>"><code><?=attributeAdminH($key)?></code></a><?php endforeach;?><?php if($undefined===[]):?><span class="text-muted">Všechny aktuálně objevené klíče mají definici.</span><?php endif;?></div></div></section>
<aside class="col-xl-5"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold"><?=$selected===null?'Nový parametr':'Upravit parametr'?></div><div class="card-body"><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="definition_id" value="<?=(int)($selected['id']??0)?>"><div class="col-12"><label class="form-label">Interní název</label><input class="form-control" name="attribute_key" maxlength="191" required value="<?=attributeAdminH($selected['attribute_key']??$newKey)?>"><div class="form-text">Krátký jednoznačný název používaný při importu, například velikost.</div></div><div class="col-12"><label class="form-label">Název pro uživatele</label><input class="form-control" name="display_name" maxlength="255" required value="<?=attributeAdminH($selected['display_name']??$newKey)?>"></div><div class="col-md-7"><label class="form-label">Druh hodnoty</label><select class="form-select" name="value_type" id="attribute-type"><option value="text" <?=($selected['value_type']??'text')==='text'?'selected':''?>>Text</option><option value="number" <?=($selected['value_type']??'')==='number'?'selected':''?>>Číslo</option><option value="choice" <?=($selected['value_type']??'')==='choice'?'selected':''?>>Výběr z nabídky</option></select></div><div class="col-md-5"><label class="form-label">Jednotka</label><input class="form-control" name="unit" maxlength="32" value="<?=attributeAdminH($selected['unit']??'')?>"></div><div class="col-md-4"><label class="form-label">Pořadí</label><input class="form-control" type="number" min="-100000" max="100000" name="sort_order" value="<?=(int)($selected['sort_order']??0)?>"></div><div class="col-md-8"><label class="form-label">Povolené hodnoty</label><textarea class="form-control" name="choice_values" rows="4" placeholder="Jedna hodnota na řádek"><?=attributeAdminH($choiceText)?></textarea><div class="form-text">Vyplňte pouze u druhu „Výběr z nabídky“.</div></div><div class="col-12 d-flex flex-wrap gap-4"><label class="form-check"><input class="form-check-input" type="checkbox" name="show_in_listing" value="1" <?=((int)($selected['show_in_listing']??0)===1)?'checked':''?>> Ve výpisu</label><label class="form-check"><input class="form-check-input" type="checkbox" name="show_in_detail" value="1" <?=((int)($selected['show_in_detail']??1)===1)?'checked':''?>> Na detailu</label><label class="form-check"><input class="form-check-input" type="checkbox" name="active" value="1" <?=((int)($selected['active']??1)===1)?'checked':''?>> Aktivní</label></div><div class="col-12"><label class="form-label">Důvod změny</label><textarea class="form-control" name="reason" minlength="3" maxlength="1000" required></textarea></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="confirm_action" value="1" id="attribute-confirm" required><label class="form-check-label" for="attribute-confirm">Potvrzuji auditovanou změnu</label></div><div class="col-12 d-grid"><button class="btn btn-primary">Uložit parametr</button></div></form></div></div></aside></div>
<section class="card border-0 shadow-sm mt-3"><div class="card-header bg-white fw-semibold">Poslední auditované změny</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Čas</th><th>Klíč</th><th>Akce</th><th>Kdo</th><th>Důvod</th></tr></thead><tbody><?php foreach($events as$event):?><tr><td><?=attributeAdminH($event['created_at'])?></td><td><code><?=attributeAdminH($event['attribute_key'])?></code></td><td><?=attributeAdminH($event['action'])?></td><td><?=attributeAdminH($event['actor_name']??('#'.$event['actor_id']))?></td><td><?=attributeAdminH($event['reason'])?></td></tr><?php endforeach;?><?php if($events===[]):?><tr><td colspan="5" class="text-center text-muted py-3">Zatím bez změn.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
